INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-05-25-changelog', '🎉 New Feature: Changelog', 1748173591768, 'feature', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The website now has a /changelog page that displays merge requests labelled with Changelog"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Visitors","marks":[{"type":"bold"}]},{"type":"text","text":" to the website can now see what is changing with the platform"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rich details","marks":[{"type":"bold"}]},{"type":"text","text":" - Each entry includes the full context from the merge request, including who contributed and when"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📰 Always up-to-date","marks":[{"type":"bold"}]},{"type":"text","text":" - No more waiting for manual changelog updates or missing important features"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🔍 Full transparency","marks":[{"type":"bold"}]},{"type":"text","text":" - See exactly what changed, when it changed, and who made it happen"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🔗 Direct links","marks":[{"type":"bold"}]},{"type":"text","text":" - Jump straight to the merge request for technical details or to contribute feedback"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⏰ Historical record","marks":[{"type":"bold"}]},{"t