INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-09-30-enhanced-shows-pages', '📺 Improvement: Enhanced Shows Pages', 1759249800000, 'improvement', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Discover your favorite shows with a beautiful new design featuring thumbnails, episode counts, and improved navigation!"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinctive icon","marks":[{"type":"bold"}]},{"type":"text","text":" - Shows now use a TV icon to distinguish them from individual videos"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Episode thumbnails","marks":[{"type":"bold"}]},{"type":"text","text":" - Each show card displays the latest episode''s thumbnail"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Episode counts","marks":[{"type":"bold"}]},{"type":"text","text":" - See at a glance how many episodes are available"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Latest episode info","marks":[{"type":"bold"}]},{"type":"text","text":" - Quick preview of the most recent episode title"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Host labels","marks":[{"type":"bold"}]},{"type":"text","text":" - Clear \"Hosted by:\" labels so you know who''s behind each show"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Better empty states","marks":[{"type":"bold"}]},{"type":"text","text":" - Shows without episodes display a friendly message instead of 404"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Refined styling","marks":[{"type":"bold"}]},{"type":"text","text":" - Enhanced header with \"Original Series\" badge and improved visual hierarchy"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 Better discovery","marks":[{"type":"bold"}]},{"type":"text","text":" - Quickly identify shows that interest you with visual previews"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📊 Episode visibility","marks":[{"type":"bold"}]},{"type":"text","text":" - Know exactly how much content is available before diving in"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✨ Improved UX","marks":[{"type":"bold"}]},{"type":"text","text":" - Smooth hover effects and transitions make browsing more enjoyable"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🎬 Show-first design","marks":[{"type":"bold"}]},{"type":"text","text":" - Treat shows as distinct series rather than just video collections"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Explore our growing collection of shows and never miss an episode!"}]}]}', NULL, 'rawkode', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Discover your favorite shows with a beautiful new design featuring thumbnails, episode counts, and improved navigation!"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinctive icon","marks":[{"type":"bold"}]},{"type":"text","text":" - Shows now use a TV icon to distinguish them from individual videos"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Episode thumbnails","marks":[{"type":"bol