INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2026-05-24-site-redesign-and-sharing', 'Site redesign and share previews', 1779624000000, 'improvement', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A broad cleanup across the academy site: simpler collection pages, clearer navigation, stronger Technology Matrix placement, refreshed organization pages, and reliable OpenGraph share images."}]}]}', NULL, 'rawkode', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The site now puts the main learning surfaces first: news, videos, articles, courses, learning paths, shows, technologies, people, and the Technology Matrix."}]},{"type":"paragraph","content":[{"type":"text","text":"This update also cleans up mobile spacing, removes repeated editorial labels, improves watch and article layouts, refreshes the organization pages, and restores large OpenGraph images for social previews."}]}]}', 1779629671000)
